```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int n;
    plik >> n;
    int max1 = n, max2 = n;
    while (plik >> n) {
        if (n > max1) {
            max2 = max1;
            max1 = n;
        } else if (n > max2) {
            max2 = n;
        }
    }
    cout << "Najwieksza wartosc: " << max1 << endl;
    cout << "Druga co do wielkosci: " << max2 << endl;
    return 0;
}
```

Weryfikacja:
- Po wczytaniu 45: max1=45, max2=45
- 12<45: bez zmian
- 78>45: max2=45, max1=78
- 34<78, 34<45: bez zmian
- 89>78: max2=78, max1=89
- Reszta < 78: bez zmian
- Wynik: max1=89, max2=78
